package com.yeyamo_mobile.api.notification_service.infrastructure.persistence;
import java.time.Instant;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.NotificationSlice;import com.yeyamo_mobile.api.notification_service.application.port.NotificationRepositoryPort;import com.yeyamo_mobile.api.notification_service.domain.Notification;
@Component public class JpaNotificationAdapter implements NotificationRepositoryPort{private final SpringNotificationRepository repo;public JpaNotificationAdapter(SpringNotificationRepository r){repo=r;}public Notification save(Notification n){NotificationEntity e=new NotificationEntity();e.id=n.id();e.sourceEventId=n.sourceEventId();e.eventType=n.eventType();e.recipientId=n.recipientId();e.title=n.title();e.body=n.body();e.dataJson=n.dataJson();e.createdAt=n.createdAt();e.readAt=n.readAt();return domain(repo.save(e));}public Optional<Notification>findById(UUID id){return repo.findById(id).map(this::domain);}public boolean exists(UUID id,String recipient){return repo.existsBySourceEventIdAndRecipientId(id,recipient);}public NotificationSlice findByRecipient(String recipient,int page,int size){var result=repo.findByRecipientIdOrderByCreatedAtDesc(recipient,PageRequest.of(page,size));return slice(page,size,result);}public NotificationSlice findUnreadByRecipient(String recipient,int page,int size){var result=repo.findByRecipientIdAndReadAtIsNullOrderByCreatedAtDesc(recipient,PageRequest.of(page,size));return slice(page,size,result);}public long countUnread(String recipient){return repo.countByRecipientIdAndReadAtIsNull(recipient);}public int markAllRead(String recipient){return repo.markAllRead(recipient,Instant.now());}public void delete(UUID id){repo.deleteById(id);}private NotificationSlice slice(int page,int size,org.springframework.data.domain.Page<NotificationEntity>result){return new NotificationSlice(page,size,result.hasNext(),result.getContent().stream().map(this::domain).toList());}private Notification domain(NotificationEntity e){return new Notification(e.id,e.sourceEventId,e.eventType,e.recipientId,e.title,e.body,e.dataJson,e.createdAt,e.readAt);}}
